const SPECIAL_LOOKUP: Record<number, NoteSpecialType> = {
  0: 'normal',
  1: 'static',
  2: 'phantom',
  3: 'ring',
};

export function buildTripleTroubleChart(): {
  notes: ChartNote[];
  events: SongEvent[];
} {
  const scale = [51, 54, 56, 57, 58, 61, 63, 66];
  const notes: ChartNote[] = TRIPLE_TROUBLE_RAW_NOTES.filter(
    (row) => (row[3] || 0) !== 3
  ).map((row, idx) => {
    const t = row[0];
    const d = row[1];
    const l = row[2] || 0;
    const specCode = row[3] || 0;
    const isPlayer = d < 4;
    const lane = (d % 4) as Direction;
    const special = SPECIAL_LOOKUP[specCode] || 'normal';
    const pitchMidi = scale[(lane * 2 + (idx % 3)) % scale.length] + (isPlayer ? 12 : 0);

    return {
      id: `tt-vslice-${idx}`,
      timeMs: t,
      lane,
      isPlayer,
      sustainMs: l,
      special,
      pitchMidi,
    };
  });

  return {
    notes,
    events: TRIPLE_TROUBLE_EVENTS.map((e) => ({ ...e })),
  };
}
